-- Coordinated cutover: stop app and worker before expanding StoreState.
-- No historical result snapshots or clinical ranges are fabricated.
CREATE OR REPLACE FUNCTION cvg_runtime_entity_collections() RETURNS text[]
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
 SELECT ARRAY['users','sessions','patients','encounters','admissions','services','reasonCodes',
  'requests','items','samples','procedures','schedules','results','resultVersions','notifications',
  'idempotency','attachments','departments','accessGroups','patientGrants','examDefinitions']::text[]
$$;
CREATE UNIQUE INDEX cvg_exam_definitions_revision_unique ON cvg_runtime_entities ((data->>'serviceId'), (data->>'serviceVersion')) WHERE collection='examDefinitions';
DO $$
DECLARE
 current_version bigint;
 previous_defaults jsonb := '{"ADMIN":["access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.view","department.create","department.update","department.deactivate","department.members.manage","service.catalog.view","realtime.connect","service.catalog.manage","sla_policy.manage","critical_result_policy.manage","reason_code.manage","user_role.manage","patient.data_export","audit.view","health.liveness","health.readiness","outbox.manage"],"MANAGER":["access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.update","department.members.manage","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","admission.context.manage","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","item.reject","item.complete","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","result.review","attachment.download","notification.acknowledge","attachment.upload_session","attachment.finalize","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","service.catalog.manage","sla_policy.manage","reason_code.manage","user_role.manage","audit.view"],"VETERINARIAN":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","patient.create","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","result.review","attachment.download","notification.acknowledge"],"INPATIENT_TEAM":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","patient.create","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","result.review","attachment.download","notification.acknowledge"],"LAB_TECH":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge","item.reject"],"RADIOLOGY_TEAM":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge"],"ULTRASOUND_TEAM":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge"],"VIEWER":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect"],"SUPERADMIN":["access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.view","department.create","department.update","department.deactivate","department.members.manage","service.catalog.view","realtime.connect","service.catalog.manage","sla_policy.manage","critical_result_policy.manage","reason_code.manage","user_role.manage","patient.data_export","audit.view","health.liveness","health.readiness","outbox.manage","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","admission.context.manage","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","item.reject","item.complete","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","result.review","attachment.download","notification.acknowledge","attachment.upload_session","attachment.finalize","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","patient.create"]}'::jsonb;
 affected_groups text[];
 group_count integer;
BEGIN
 SELECT version INTO current_version FROM cvg_runtime_state WHERE id=1 FOR UPDATE;
 IF current_version IS NOT NULL THEN
  -- Only unchanged system profiles receive their new command. A reduced matrix
  -- keeps exactly its chosen grants; an administrator can review it explicitly.
  WITH changed AS (
   UPDATE cvg_runtime_entities SET data=data || jsonb_build_object('permissions',(data->'permissions') || '["exam_definition.approve"]'::jsonb,
     'version',(data->>'version')::integer+1,'updatedAt',to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
     written_version=current_version+1
   WHERE collection='accessGroups' AND data->>'systemRole' IN ('SUPERADMIN','MANAGER','VETERINARIAN')
    AND (data->'permissions') @> (previous_defaults->(data->>'systemRole'))
    AND (previous_defaults->(data->>'systemRole')) @> (data->'permissions')
   RETURNING entity_key
  ) SELECT array_agg(entity_key),count(*) INTO affected_groups,group_count FROM changed;
  UPDATE cvg_runtime_entities SET data=data || jsonb_build_object('version',(data->>'version')::integer+1),written_version=current_version+1
   WHERE collection='users' AND data->>'accessGroupId'=ANY(affected_groups);
  UPDATE cvg_runtime_entities AS session SET data=session.data || jsonb_build_object('revokedAt',to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'version',(session.data->>'version')::integer+1),written_version=current_version+1
   WHERE session.collection='sessions' AND NOT session.data ? 'revokedAt' AND EXISTS(SELECT 1 FROM cvg_runtime_entities AS target
    WHERE target.collection='users' AND target.data->>'id'=session.data->>'userId' AND target.data->>'accessGroupId'=ANY(affected_groups));
  UPDATE cvg_runtime_state SET state=cvg_runtime_state_header(state),version=current_version+1,updated_at=now() WHERE id=1;
  INSERT INTO audit_events(id,event_type,entity_type,entity_id,correlation_id,metadata,occurred_at)
   VALUES('audit-migration-021','ExamDefinitionsEnabled','SchemaMigration','021_exam_definitions','corr-migration-021',
    jsonb_build_object('systemGroupsUpdated',group_count,'historicalSnapshotsFabricated',false,'clinicalScopeChanged',false),CURRENT_TIMESTAMP);
 END IF;
END $$;
ALTER TABLE cvg_runtime_state ADD CONSTRAINT runtime_exam_definitions_are_external CHECK(COALESCE(state->'examDefinitions'='[]'::jsonb,false));
UPDATE relational_schema_markers SET schema_version='021_exam_definitions' WHERE marker_key='RELATIONAL_CLINICAL_CORE_EXPAND_V1';
